sections.excerpt:
	[[fallthrough]];
case RS::CANVAS_ITEM_TEXTURE_FILTER_LINEAR_WITH_MIPMAPS: {
	pmag = GL_LINEAR;
	if (mipmaps <= 1) {
		pmin = GL_LINEAR;
		max_lod = 0;
	} else if (config->use_nearest_mip_filter) {
		pmin = GL_LINEAR_MIPMAP_NEAREST;
		max_lod = 1000;
	} else {
		pmin = GL_LINEAR_MIPMAP_LINEAR;
		max_lod = 1000;
	}
} break;
default: {

		if (mipmaps <= 1) {
			pmin = GL_LINEAR;
			max_lod = 0;
		} else if (config->use_nearest_mip_filter) {
			pmin = GL_LINEAR_MIPMAP_NEAREST;
			max_lod = 1000;
		} else {
			pmin = GL_LINEAR_MIPMAP_LINEAR;
			max_lod = 1000;
		}
	} break;
	default: {
		return;
	} break;
}
